CREATE VIEW "public"."daily_margin_by_site" AS (select "project_id", "location_id", "trx_date", coalesce(sum(case when "kind" = 'sales' then "total" else 0 end), 0) as "sales", coalesce(sum(case when "kind" = 'cost' then "total" else 0 end), 0) as "cost", coalesce(sum(case when "kind" = 'sales' then "total" else -"total" end), 0) as "margin" from "daily_transactions" group by "daily_transactions"."project_id", "daily_transactions"."location_id", "daily_transactions"."trx_date");